import Redis from "ioredis";

const MAX_FEED_SIZE = 200;

interface ScoredPost {
  score: number;
  member: string;
}

/**
 * Seeds a user's ranked feed sorted set and trims it to the configured max size.
 */
export async function seedFeed(userId: string, posts: ScoredPost[]): Promise<void> {
  const redis = new Redis({
    host: process.env.REDIS_HOST,
    port: Number(process.env.REDIS_PORT ?? 6379),
  });

  const key = `feed:${userId}`;

  for (const post of posts) {
    await redis.zadd(key, post.score, post.member);
  }

  await redis.zremrangebyrank(key, 0, -(MAX_FEED_SIZE + 1));
}
